### Description

Using decorator assertions broke in what I assume was #3317. `AssertionError [ERR_ASSERTION]: The decorator 'someThing' required by 'custom-plugin-two' is not present in Request`

### Steps to Reproduce

```js
const fastify = require('fastify');
const fp = require('fastify-plugin');

const plugin1 = fp(
  async (instance) => {
    instance.decorateRequest('someThing', null);

    instance.addHook('onRequest', async (request, reply) => {
      request.someThing = 'hello';
    });
  },
  {
    name: 'custom-plugin-one',
    fastify: '3.x',
  }
);

const plugin2 = fp(
  async () => {
    // nothing
  },
  {
    name: 'custom-plugin-two',
    fastify: '3.x',
    dependencies: ['custom-plugin-one'],
    decorators: {
      request: ['someThing'],
    },
  }
);

const app = fastify();

app.register(plugin1);
app.register(plugin2);

app.listen(0).then(
  () => {
    console.log('no error!');

    process.exit(0);
  },
  (error) => {
    console.error('Got error', error);

    process.exit(1);
  }
);
```

Using 3.21.1 this works fine, but 3.21.2 and 3.21.3 throws an assertion error

### Expected Behavior

No error
